import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, vec2, fract, sin, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'hub-journal-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Atlas region: 512x320 => aspect 1.6
  const planeW = 1.6;
  const planeH = 1.0;
  const geo = new THREE.PlaneGeometry(planeW, planeH, 1, 1);

  const inkCol = uniform(new THREE.Color(colors.ink));
  const surfCol = uniform(new THREE.Color(colors.surface));
  const accentCol = uniform(new THREE.Color(colors.accent));

  const vUv = uv();

  // Engineered vertical gradient: surface (bottom) -> ink (top)
  const gradY = smoothstep(float(0.0), float(1.0), vUv.y);
  const baseGrad = mix(surfCol, inkCol, gradY);

  // Subtle accent edge band near top — contained, <=10% of frame
  const accentBand = smoothstep(float(0.86), float(0.92), vUv.y).mul(
    smoothstep(float(1.0), float(0.94), vUv.y)
  );
  const withAccent = mix(baseGrad, accentCol, accentBand.mul(float(0.45)));

  // Subtle grain (static — time gated to 0)
  const g = fract(sin(vUv.mul(vec2(420.0, 420.0))).mul(float(43758.5453)));
  const grainAmt = float(0.02);
  const grained = withAccent.add(vec3(g.sub(float(0.5)).mul(grainAmt)));

  const mat = new MeshBasicNodeMaterial();
  mat.colorNode = grained;
  mat.transparent = true;

  // Overlay brushed-metal streaks from the texture (subtle darkening)
  ctx.textureLoader.loadTexture('/prism-assets/chrome/brushed-metal.map.png')
    .then((t) => {
      const streak = t.tex.r.sub(float(0.5)).mul(float(0.12));
      mat.colorNode = grained.add(vec3(streak));
      mat.needsUpdate = true;
    })
    .catch(() => {});

  const plane = new THREE.Mesh(geo, mat);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // MSDF text — "Journal 1" headline 39px on paper color
  for (const item of items) {
    if (!item || !item.text) continue;
    const fs = item.typography?.fontSize ?? 39;
    const txt = ctx.fontAtlas.createText(String(item.text), {
      fontSize: fs,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 480,
      letterSpacingPx: 0.6,
    });
    txt.position.set(0, 0, 0.012);
    txt.rotation.set(0, 0, 0);
    group.add(txt);
  }

  // Weighted-settle entrance: rise + 1.04 -> 1.0 over 0.9s power4.out
  const tl = gsap.timeline();
  tl.from(group.position, { y: '+=0.2', duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' }, 0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
  };

  return group;
}
